CREATE TABLE IF NOT EXISTS user_handles(user_id TEXT PRIMARY KEY REFERENCES users(id),username TEXT NOT NULL UNIQUE,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS class_subjects(class_id TEXT NOT NULL REFERENCES academics(id),subject_id TEXT NOT NULL REFERENCES academics(id),PRIMARY KEY(class_id,subject_id));
CREATE TABLE IF NOT EXISTS teacher_reviewers(teacher_id TEXT PRIMARY KEY REFERENCES users(id),head_id TEXT NOT NULL REFERENCES users(id),CHECK(teacher_id<>head_id));
CREATE TABLE IF NOT EXISTS connections(id TEXT PRIMARY KEY,user_low TEXT NOT NULL REFERENCES users(id),user_high TEXT NOT NULL REFERENCES users(id),sender_id TEXT NOT NULL REFERENCES users(id),recipient_id TEXT NOT NULL REFERENCES users(id),state TEXT NOT NULL CHECK(state IN('pending','accepted','rejected','cancelled','removed')),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(user_low,user_high),CHECK(user_low<user_high));
CREATE TABLE IF NOT EXISTS user_blocks(user_id TEXT NOT NULL REFERENCES users(id),blocked_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,PRIMARY KEY(user_id,blocked_id),CHECK(user_id<>blocked_id));
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN('direct','group')),name TEXT NOT NULL,creator_id TEXT NOT NULL REFERENCES users(id),connection_id TEXT UNIQUE REFERENCES connections(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversation_members(conversation_id TEXT NOT NULL REFERENCES conversations(id),user_id TEXT NOT NULL REFERENCES users(id),active INTEGER NOT NULL DEFAULT 1,last_read_at TEXT,joined_at TEXT NOT NULL,PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS membership_events(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),user_id TEXT NOT NULL REFERENCES users(id),actor_id TEXT NOT NULL REFERENCES users(id),action TEXT NOT NULL CHECK(action IN('joined','removed','left')),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chat_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),sender_id TEXT NOT NULL REFERENCES users(id),client_id TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(sender_id,client_id));
CREATE TABLE IF NOT EXISTS communication_reports(id TEXT PRIMARY KEY,reporter_id TEXT NOT NULL REFERENCES users(id),reported_user_id TEXT NOT NULL REFERENCES users(id),conversation_id TEXT REFERENCES conversations(id),reason TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS connection_recipient ON connections(recipient_id,state);
CREATE INDEX IF NOT EXISTS chat_conversation_time ON chat_messages(conversation_id,created_at,id);
CREATE INDEX IF NOT EXISTS members_user ON conversation_members(user_id,active);
INSERT OR IGNORE INTO user_handles SELECT id,'u_' || replace(id,'-',''),created_at FROM users;
INSERT OR IGNORE INTO class_subjects SELECT DISTINCT s.parent_id,a.subject_id FROM assignments a JOIN academics s ON s.id=a.section_id WHERE s.parent_id IS NOT NULL;
INSERT OR IGNORE INTO teacher_reviewers SELECT teacher_id,MIN(head_id) FROM assignments WHERE active=1 AND NOT EXISTS(SELECT 1 FROM migrations WHERE version=3) GROUP BY teacher_id HAVING COUNT(DISTINCT head_id)=1;
CREATE TRIGGER IF NOT EXISTS membership_events_no_update BEFORE UPDATE ON membership_events BEGIN SELECT RAISE(ABORT,'Communication history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS membership_events_no_delete BEFORE DELETE ON membership_events BEGIN SELECT RAISE(ABORT,'Communication history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS chat_messages_no_update BEFORE UPDATE ON chat_messages BEGIN SELECT RAISE(ABORT,'Communication history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS chat_messages_no_delete BEFORE DELETE ON chat_messages BEGIN SELECT RAISE(ABORT,'Communication history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS communication_reports_no_update BEFORE UPDATE ON communication_reports BEGIN SELECT RAISE(ABORT,'Communication history is append-only'); END;
CREATE TRIGGER IF NOT EXISTS communication_reports_no_delete BEFORE DELETE ON communication_reports BEGIN SELECT RAISE(ABORT,'Communication history is append-only'); END;
INSERT OR IGNORE INTO migrations VALUES(3,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE IF NOT EXISTS chat_media(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),uploader_id TEXT NOT NULL REFERENCES users(id),mime TEXT NOT NULL,name TEXT NOT NULL,size INTEGER NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS chat_media_conversation ON chat_media(conversation_id,created_at);
